WITH with_windows AS (SELECT id, customer_id, status, LEAD(balance, 1) OVER (PARTITION BY customer_id ORDER BY balance, id) AS next_balance, AVG(balance) OVER (PARTITION BY status, customer_id) AS status_avg_balance FROM accounts), latest AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY next_balance DESC, id) AS latest_rank FROM with_windows) ranked WHERE latest_rank = 1), remaining_keys AS (SELECT id FROM latest EXCEPT DISTINCT SELECT id FROM accounts WHERE opened_date > '2023-08-01'), verified AS (SELECT s.* FROM latest s INNER JOIN remaining_keys k ON s.id = k.id), kept_keys AS (SELECT status FROM verified INTERSECT SELECT status FROM accounts WHERE MONTH(opened_date) IN (1, 3, 10)), kept_rows AS (SELECT s.* FROM verified s INNER JOIN kept_keys k ON s.status = k.status), enriched AS (SELECT *, PERCENT_RANK() OVER (ORDER BY status_avg_balance NULLS LAST) AS status_avg_balance_percent_rank, MAX(status_avg_balance) OVER (PARTITION BY customer_id) AS customer_id_max_status_avg_balance FROM kept_rows), joined AS (SELECT s.*, p.credit_limit, p.segment, p.age FROM enriched s LEFT JOIN customers p ON s.customer_id = p.id WHERE p.city = 'Singapore') SELECT customer_id, SORT_ARRAY(COLLECT_SET(status)) AS status_list, AVG(status_avg_balance_percent_rank) AS avg_status_avg_balance_percent_rank, SORT_ARRAY(COLLECT_SET(status)) AS status_list_2, MAX(status_avg_balance_percent_rank) FILTER (WHERE status = 'CLOSED') AS closed_max_status_avg_balance_percent_rank, COUNT(*) AS row_count FROM joined GROUP BY customer_id ORDER BY closed_max_status_avg_balance_percent_rank DESC;
